event-ledger:
function summarize(rows) {
  const seen = new Set(), counts = Object.create(null);
  for (const row of rows) {
    if (!row || typeof row !== "object" || typeof row.id !== "string" || !row.id.trim() || typeof row.user !== "string" || !row.user.trim() || !["ok", "fail"].includes(row.status)) continue;
    const id = row.id.trim(), user = row.user.trim();
    if (seen.has(id)) continue;
    seen.add(id);
    if (row.status === "fail") counts[user] = (counts[user] || 0) + 1;
  }
  return counts;
}

