function diagnose(c) {
  const issues = [];
  if (c.listener === "127.0.0.1") issues.push("listener");
  if (c.publishedPort !== c.appPort) issues.push("publish");
  if (c.targetPort !== c.appPort) issues.push("service");
  if (c.reportedHealthy !== (c.probeExit === 0)) issues.push("health");
  return issues;
}

login-window:
def investigate(events):
    unique = {}
    for event in events:
        if event["id"] not in unique:
            unique[event["id"]] = event
    rows = list(unique.values())
    findings = []
    for success in sorted(rows, key=lambda e: (e["minute"], e["id"])):
        if success["result"] != "Success":
            continue
        count = sum(1 for e in rows if e["result"] == "Failure" and e["user"] == success["user"] and e["ip"] == success["ip"] and success["minute"] - 5 <= e["minute"] < success["minute"])
        if count >= 3:
            findings.append({"id": success["id"], "failures": count})
    return findings

coverage-union:
function coverage(intervals) {
  const sorted = intervals.map(x => [...x]).sort((a,b) => a[0]-b[0]);
  let total=0, end=-Infinity;
  for(const [a,b] of sorted) {total+=Math.max(0,b-Math.max(a,end));end=Math.max(end,b);}
  return total;
}

dependency-waves:
def waves(graph):
    pending = {name: set(deps) for name, deps in graph.items()}
    result = []
    while pending:
        ready = sorted(name for name, deps in pending.items() if not deps)
        if not ready:
            return None
        result.append(ready)
        for name in ready:
            del pending[name]
        for deps in pending.values():
            deps.difference_update(ready)
    return result

lru-replay:
function replayCache(input) {
  const cache=new Map(), output=[];
  for(const [op,key,value] of input.operations) {
    if(op==='get') {
      if(!cache.has(key)){output.push(null);continue;}
      const found=cache.get(key);output.push(found);cache.delete(key);cache.set(key,found);
    } else if(input.capacity>0) {
      cache.delete(key);cache.set(key,value);
      if(cache.size>input.capacity)cache.delete(cache.keys().next().value);
    }
  }
  return output;
}

