function decodeFrames(chunks) {
 const stream=chunks.join(''), frames=[];let pos=0;
 const result=error=>({frames,remainder:stream.slice(pos),error});
 while(pos<stream.length){
  let cursor=pos, digits='';
  while(cursor<stream.length && /[0-9]/.test(stream[cursor])){
   digits+=stream[cursor++];
   if(digits.length>3 || (digits.length>1 && digits[0]==='0') || Number(digits)>255)return result(true);
  }
  if(cursor===stream.length)return result(false);
  if(!digits || stream[cursor]!==':')return result(true);
  const end=cursor+1+Number(digits);
  if(end>=stream.length)return result(false);
  if(stream[end]!==',')return result(true);
  frames.push(stream.slice(cursor+1,end));pos=end+1;
 }
 return result(false);
}

transaction-replay:
def recover(input):
    state = dict(input['initial'])
    active = {}
    for row in input['log']:
        op, tx = row[:2]
        if op == 'begin':
            if tx not in active:
                active[tx] = []
        elif tx in active:
            if op in ('set', 'delete'):
                active[tx].append(row)
            elif op == 'abort':
                del active[tx]
            elif op == 'commit':
                for change in active.pop(tx):
                    if change[0] == 'set':
                        state[change[2]] = change[3]
                    else:
                        state.pop(change[2], None)
    return state

byte-machine:
function execute(input) {
 const registers=[0,0,0,0];let pc=0,steps=0;
 const done=reason=>({registers,pc,steps,reason});
 while(true){
  if(pc<0||pc>=input.program.length)return done('exit');
  if(steps===input.limit)return done('limit');
  const [op,r,s]=input.program[pc];steps++;
  if(op==='HALT')return done('halt');
  if(op==='SET')registers[r]=((s%256)+256)%256;
  if(op==='ADD')registers[r]=(registers[r]+registers[s])%256;
  if(op==='XOR')registers[r]=registers[r]^registers[s];
  pc+=op==='JNZ'&&registers[r]!==0?s:1;
 }
}
